"""Read-only native prescribed-boundary evidence; never replace missing SDK numbers."""
import hashlib,json,pathlib,re,struct,numpy as np
ROOT=pathlib.Path('.bench-work/commercial-246/pkpm-batch01');OUT=pathlib.Path('.bench-work/commercial-246/pkpm-independent-review')
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def native_text(p):return p.read_bytes().decode('gb18030',errors='strict')
def node_rows(t):
 chunk=t.split('# 节点信息',1)[1].split('# 网格线信息',1)[0];rows={}
 for match in re.finditer(r'^#(\d+):([^\r\n]+)\r?\n([^\r\n]+)',chunk,re.M):rows[int(match[1])]={'header':match[2],'values':[float(x) for x in match[3].rstrip(',').split(',')]}
 return rows
rows=[];quantityrows=[]
for bind in read(ROOT/'local-bindings.json'):
 if bind['caseId'] not in ['STD-080','STD-082','STD-083','STD-086']:continue
 case=bind['caseId'];p=ROOT/'remote-evidence'/bind['nativeIdentity'];cp=pathlib.Path('corpora/research-300/cases')/case;model=read(cp/'model-state-1.json');assert sha(cp/'model-state-1.json')==bind['sourceModelSha256'];packet=read(p/'physical-input.json');assert sha(p/'physical-input.json')==bind['physicalPacketSha256'];sdk=read(p/'sdk-results.json');txt=native_text(p/'spas_sat.txt');wm=native_text(p/'WMASS.OUT');nr=node_rows(txt);mesh=np.frombuffer((p/'MESH.SAT').read_bytes(),dtype='<f4')[5:].reshape(-1,5);meshints=np.frombuffer((p/'MESH.SAT').read_bytes(),dtype='<i4')[5:].reshape(-1,5);assert len(nr)==len(mesh)==len(model['nodes']);cn=(p/'ConstraintNodeNo.SAT').read_bytes();head=struct.unpack_from('<4i',cn);assert head==(3,20200113,len(mesh),4);assert all(x==0 for x in struct.unpack_from('<%di'%len(mesh),cn,16));assert not (p/'ConstraintNode.SAT').exists() and not (p/'ConstraintNodeSK.SAT').exists()
 assert re.search(r'# 约束节点类型信息\s+0\s',txt);assert re.search(r'嵌固端所在层号:\s+MQIANGU=\s+1',wm);doflines=[l.strip() for l in wm.splitlines() if '自由度为' in l];dofs=[int(l.split(':')[-1]) for l in doflines];upper=[n for n in model['nodes'] if not any(n['restraints'])];base=[n for n in model['nodes'] if all(n['restraints'])];assert len(base)+len(upper)==len(model['nodes']);assert dofs==[6*len(upper)]*2
 ni=np.frombuffer((p/'NODEINDEX.SAT').read_bytes(),dtype='<f4');stories=len(model['stories']);counts=[int(x) for x in ni[:stories]];nids=[int(x) for x in ni[stories::2]];assert len(ni)==stories+2*sum(counts);assert sum(counts)==len(upper);assert (p/'DISP.SAT').stat().st_size==2*6*len(upper)*4;assert all(ni[stories+1::2]==0)
 nmap={};baseproof=[]
 for n in model['nodes']:
  xyz=np.array([n[a] for a in 'xyz']);hits=[i+1 for i,v in enumerate(mesh) if np.allclose(v[:3],xyz,rtol=0,atol=1e-6)];assert len(hits)==1;idx=hits[0];nmap[n['id']]=idx;r=nr[idx];v=r['values'];assert np.allclose(np.array(v[1:4])/1000,xyz,rtol=0,atol=1e-6)
  if all(n['restraints']):
   assert idx not in nids and meshints[idx-1,3]==-1;assert v[4:10]==[1]*6 and v[10:16]==[-1]*6 and v[20]==0;ss=[sn for sn in sdk['nodes'] if np.allclose(np.array(sn['coordinates'])/1000,xyz,rtol=0,atol=1e-6)];assert len(ss)==1 and ss[0]['cases']['DL']==[-99999]*3
   baseproof.append({'sourceNode':n['id'],'nativeMeshIndex':idx,'coordinateM':xyz.tolist(),'nativeNodeHeader':r['header'],'nativeTextColumns4through15':v[4:16],'nativeSpecialOverrideColumn20':v[20],'nativeMeshIntFlag':int(meshints[idx-1,3]),'absentFromNODEINDEX':True,'rawSDKDL':ss[0]['cases']['DL']})
  else:assert idx in nids and meshints[idx-1,3]==100 and v[4:16]==[0]*12
 request=read(cp/'reference-requests.json');cqs=[]
 for state in request['states']:
  for q in state['quantities']:
   loc=q['location'];nid=loc.get('id');nn=next((n for n in base if n['id']==nid),None)
   if loc['kind']=='node' and nn is not None and q['component'] in ['ux','uy']:
    row={'case':case,'state':state['state'],'quantityId':q['id'],'selection':q['selection'],'component':q['component'],'node':nid,'nativeMeshIndex':nmap[nid],'SDKRawValue':-99999,'SDKValueStatus':'unavailable','proposedSeparateBoundaryDerivedValue':0.0,'proposedValueKind':'derived-from-native-prescribed-boundary','caseQualificationChanged':False};quantityrows.append(row);cqs.append(q['id'])
 rows.append({'case':case,'nativeIdentity':bind['nativeIdentity'],'physicalNodes':len(mesh),'fixedBaseNodes':len(base),'unrestrainedUpperNodes':len(upper),'executedNativeDOFLines':doflines,'ordinaryFreeSixDOFs':6*len(upper),'DISPBytes':(p/'DISP.SAT').stat().st_size,'noSpecialSupportDefinitionOrOverride':True,'embeddedLevelReported':1,'baseNodes':baseproof,'affectedQuantityIds':cqs,'sources':{str(f):sha(f) for f in [cp/'model-state-1.json',cp/'reference-requests.json',p/'physical-input.json',p/'spas_sat.txt',p/'WMASS.OUT',p/'MESH.SAT',p/'NODEINDEX.SAT',p/'DISP.SAT',p/'ConstraintNodeNo.SAT',p/'sdk-results.json']}})
assert len(quantityrows)==58
pin=pathlib.Path('.bench-work/commercial-246/pkpm-extra01/remote-evidence/c30-b-pincontrol');pt=native_text(pin/'spas_sat.txt');pr=node_rows(pt);assert pr[1]['values'][20]==1;pw=native_text(pin/'WMASS.OUT');assert [int(l.split(':')[-1]) for l in pw.splitlines() if '自由度为' in l]==[30,30];assert (pin/'DISP.SAT').stat().st_size==2*30*4
report={'kind':'Native prescribed-boundary derivation review','recommendation':'Evidence supports a separately typed derived-from-native-prescribed-boundary value of zero for exactly these 58 quantities, conditional on retaining this complete executed-boundary chain. Preserve original SDK unavailable sentinel and do not label the derived value an SDK displacement. No acceptance or candidate file edited.','evidenceReasoning':['Executed native text embeds level 1 and has identical six-column constrained patterns at every mapped ground node, while every retained upper node has the complementary unconstrained pattern.','No special support definitions or overrides: native ConstraintNodeNo is zero for every physical node and ConstraintNode/SK files are absent.','Executed native total DOFs equal exactly six times all upper nodes; NODEINDEX excludes exactly the mapped bases and DISP length contains exactly those upper six-DOF solutions. Thus the standard fixed-base directions are prescribed/eliminated from the solved unknowns, not the additional finite-spring unknowns observed in the pin control.','The independently solved pin control is a counterexample to using flags or missing outputs alone: identical base flags with a nonzero special override retain all six base DOFs, WMASS increases from24 to30, and DISP resolves finite translation compliance.','Zero is the prescribed homogeneous fixed-base value in this no-settlement linear-static input; it is a mathematical consequence of the executed boundary, not an inferred response or a replacement of missing SDK output.'],'limitations':['No official spas_sat field dictionary was locally available; the report preserves exact observed columns and multiple independent native artifacts rather than asserting one undocumented field alone proves its semantics.','This derivation is scoped to these four ordinary fully fixed-base runs; do not apply to spring/pin, partial restraints, imposed settlements, rigid links, MPCs, nonhomogeneous conditions or other solver versions without new evidence.','Neither a direct native displacement vector nor per-equation elimination table was returned for these bases. The value kind must remain boundary-derived, with the raw SDK missing retained.'],'benchmarkCasesQualified':0,'runs':rows,'quantities':quantityrows,'pinCounterexample':{'nativeIdentity':'c30-b-pincontrol','sameBaseTextPattern':pr[1]['values'][4:16],'specialOverrideColumn20':1,'nativeTotalDOFs':30,'ordinaryUpperDOFs':24,'additionalBaseDOFs':6,'nativeTranslationPenalty':1e14,'sources':{str(f):sha(f) for f in [pin/'spas_sat.txt',pin/'WMASS.OUT',pin/'DISP.SAT',pin/'native-pin-postsolve.json',OUT/'extra01/pin-control-review.json']}},'sourceBindingsSha256':sha(ROOT/'local-bindings.json'),'reviewScriptSha256':sha(pathlib.Path(__file__))}
(OUT/'fixed-boundary-derived-review.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'runs':[{k:r[k] for k in ['case','fixedBaseNodes','ordinaryFreeSixDOFs']}|{'quantities':len(r['affectedQuantityIds'])} for r in rows],'quantityCount':len(quantityrows),'recommendation':report['recommendation']}))
